//! Rust source for `mc-bindings/src/generated.rs` and
//! `mc-versions/src/supported.rs`.

use std::fmt::Write as _;

use crate::resolve::{ApiClass, ApiMember, Binding, Kind, Model};

const HEADER: &str =
    "// @generated by `cargo xtask bindgen` from `mc-data/` — do not edit by hand.\n";

/// One JNI value type of a descriptor.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Ty {
    Prim(char),
    Object,
}

/// Splits `(params)ret` into parameter types and the return type.
fn method_types(descriptor: &str) -> (Vec<Ty>, Ty) {
    let (params, ret) = descriptor
        .strip_prefix('(')
        .and_then(|rest| rest.split_once(')'))
        .unwrap_or(("", descriptor));
    (
        field_types(params),
        field_types(ret).first().copied().unwrap_or(Ty::Prim('V')),
    )
}

fn field_types(descriptor: &str) -> Vec<Ty> {
    let mut out = Vec::new();
    let mut chars = descriptor.chars();
    while let Some(c) = chars.next() {
        match c {
            '[' => {
                // Skip the element type: the whole array is one object.
                for inner in chars.by_ref() {
                    if inner == 'L' {
                        for end in chars.by_ref() {
                            if end == ';' {
                                break;
                            }
                        }
                        break;
                    }
                    if inner != '[' {
                        break;
                    }
                }
                out.push(Ty::Object);
            }
            'L' => {
                for end in chars.by_ref() {
                    if end == ';' {
                        break;
                    }
                }
                out.push(Ty::Object);
            }
            other => out.push(Ty::Prim(other)),
        }
    }
    out
}

fn param_type(ty: Ty) -> &'static str {
    match ty {
        Ty::Prim('Z') => "bool",
        Ty::Prim('B') => "i8",
        Ty::Prim('C') => "u16",
        Ty::Prim('S') => "i16",
        Ty::Prim('I') => "i32",
        Ty::Prim('J') => "i64",
        Ty::Prim('F') => "f32",
        Ty::Prim('D') => "f64",
        _ => "&JObject<'_>",
    }
}

fn return_type(ty: Ty) -> &'static str {
    match ty {
        Ty::Prim('V') => "()",
        Ty::Object => "JObject<'l>",
        other => param_type(other),
    }
}

/// Unwraps a `JValueOwned` of type `ty`.
fn accessor(ty: Ty) -> &'static str {
    match ty {
        Ty::Prim('Z') => "z",
        Ty::Prim('B') => "b",
        Ty::Prim('C') => "c",
        Ty::Prim('S') => "s",
        Ty::Prim('I') => "i",
        Ty::Prim('J') => "j",
        Ty::Prim('F') => "f",
        Ty::Prim('D') => "d",
        Ty::Prim('V') => "v",
        _ => "l",
    }
}

/// `jni::signature::ReturnType` for a method returning `descriptor`'s type.
fn return_type_const(descriptor: &str) -> &'static str {
    let ret = descriptor.rsplit(')').next().unwrap_or(descriptor);
    match ret.as_bytes().first() {
        Some(b'Z') => "ReturnType::Primitive(Primitive::Boolean)",
        Some(b'B') => "ReturnType::Primitive(Primitive::Byte)",
        Some(b'C') => "ReturnType::Primitive(Primitive::Char)",
        Some(b'S') => "ReturnType::Primitive(Primitive::Short)",
        Some(b'I') => "ReturnType::Primitive(Primitive::Int)",
        Some(b'J') => "ReturnType::Primitive(Primitive::Long)",
        Some(b'F') => "ReturnType::Primitive(Primitive::Float)",
        Some(b'D') => "ReturnType::Primitive(Primitive::Double)",
        Some(b'[') => "ReturnType::Array",
        Some(b'L') => "ReturnType::Object",
        _ => "ReturnType::Primitive(Primitive::Void)",
    }
}

fn jvalue(name: &str, ty: Ty) -> String {
    match ty {
        Ty::Object => format!("JValue::Object({name}).as_jni()"),
        _ => format!("JValue::from({name}).as_jni()"),
    }
}

/// Version ids of every group, for docs: `26.1, 26.1.1, 26.1.2`.
fn group_versions(model: &Model, group: usize) -> String {
    model
        .versions
        .iter()
        .zip(&model.groups)
        .filter(|(_, g)| **g == group)
        .map(|((id, _), _)| id.as_str())
        .collect::<Vec<_>>()
        .join(", ")
}

/// Bindings per group (each group's first version is representative), and
/// the groups sharing each distinct binding, in group order.
fn arms<T: Clone + PartialEq>(model: &Model, per_version: &[T]) -> Vec<(Vec<usize>, T)> {
    let mut arms: Vec<(Vec<usize>, T)> = Vec::new();
    for group in 0..model.group_count {
        let first = model.groups.iter().position(|g| *g == group).unwrap();
        let value = per_version[first].clone();
        match arms.iter_mut().find(|(_, other)| *other == value) {
            Some((groups, _)) => groups.push(group),
            None => arms.push((vec![group], value)),
        }
    }
    arms
}

/// `match crate::group(cx) { … }` over `arms`, the last one as the catch-all.
fn emit_match(out: &mut String, arms: &[(Vec<usize>, String)]) {
    if arms.len() == 1 {
        out.push_str(&arms[0].1);
        out.push('\n');
        return;
    }
    out.push_str("match crate::group(cx) {\n");
    for (index, (groups, body)) in arms.iter().enumerate() {
        let pattern = if index + 1 == arms.len() {
            "_".to_string()
        } else {
            groups
                .iter()
                .map(usize::to_string)
                .collect::<Vec<_>>()
                .join(" | ")
        };
        let _ = writeln!(out, "{pattern} => {body},");
    }
    out.push_str("}\n");
}

fn member_doc(out: &mut String, model: &Model, class: &ApiClass, member: &ApiMember) {
    let what = match member.kind {
        Kind::Constructor => format!("Constructor `{}`", member.descriptor),
        Kind::Field => format!("Field `{}: {}`", member.java, member.descriptor),
        Kind::Method => format!("`{}{}`", member.java, member.descriptor),
    };
    let _ = writeln!(
        out,
        "/// {what}{}.",
        if member.is_static { ", static" } else { "" }
    );
    // What each version calls, rendered; versions reading the same share a line.
    let mut lines: Vec<(Vec<String>, String)> = Vec::new();
    for (groups, binding) in arms(model, &member.bindings) {
        let first = model.groups.iter().position(|g| *g == groups[0]).unwrap();
        let own_class = class.names[first].as_deref().unwrap_or_default();
        let how = match binding {
            Binding::Direct {
                class: owner,
                name,
                descriptor,
                ..
            } => {
                let separator = if member.kind == Kind::Field { ": " } else { "" };
                let owner = if owner == own_class {
                    String::new()
                } else {
                    format!("{owner}.")
                };
                format!("`{owner}{name}{separator}{descriptor}`")
            }
            Binding::Shim(function) => format!("shim `{function}`"),
            Binding::Unavailable => "unavailable".to_string(),
        };
        let versions = groups.iter().map(|group| group_versions(model, *group));
        match lines.iter_mut().find(|(_, other)| *other == how) {
            Some((existing, _)) => existing.extend(versions),
            None => lines.push((versions.collect(), how)),
        }
    }
    if lines.len() > 1 {
        out.push_str("///\n");
        for (versions, how) in lines {
            let _ = writeln!(out, "/// - {}: {how}", versions.join(", "));
        }
    }
}

fn emit_member(
    out: &mut String,
    model: &Model,
    class: &ApiClass,
    member: &ApiMember,
) -> Result<(), String> {
    let label = format!("{}.{}", class.rust, member.java);
    let (params, ret) = match member.kind {
        Kind::Field => (Vec::new(), field_types(&member.descriptor)[0]),
        Kind::Constructor => (method_types(&member.descriptor).0, Ty::Object),
        Kind::Method => method_types(&member.descriptor),
    };
    let has_this = !member.is_static && member.kind != Kind::Constructor;
    let arg_names: Vec<String> = (0..params.len()).map(|i| format!("arg{i}")).collect();

    let mut signature = String::from("cx: &mut Cx<'l>");
    if has_this {
        signature.push_str(", this: &JObject<'_>");
    }
    for (name, ty) in arg_names.iter().zip(&params) {
        let _ = write!(signature, ", {name}: {}", param_type(*ty));
    }
    let jni_args = arg_names
        .iter()
        .zip(&params)
        .map(|(name, ty)| jvalue(name, *ty))
        .collect::<Vec<_>>()
        .join(", ");
    let this = if has_this { "this" } else { "&JObject::null()" };
    let shim_args = std::iter::once("cx".to_string())
        .chain(has_this.then(|| "this".to_string()))
        .chain(arg_names.iter().cloned())
        .collect::<Vec<_>>()
        .join(", ");

    member_doc(out, model, class, member);
    let _ = writeln!(
        out,
        "pub fn {}<'l>({signature}) -> Result<{}> {{",
        member.rust,
        return_type(ret)
    );

    // One static target per distinct direct binding.
    let mut statics: Vec<&Binding> = Vec::new();
    for binding in &member.bindings {
        if matches!(binding, Binding::Direct { .. }) && !statics.contains(&binding) {
            statics.push(binding);
        }
    }
    for (index, binding) in statics.iter().enumerate() {
        let Binding::Direct {
            class: owner,
            name,
            descriptor,
            is_static,
        } = binding
        else {
            unreachable!()
        };
        match member.kind {
            Kind::Field => {
                let _ = writeln!(
                    out,
                    "static T{index}: Field = Field::new({owner:?}, {name:?}, {descriptor:?}, {is_static});"
                );
            }
            _ => {
                let _ = writeln!(
                    out,
                    "static T{index}: Method = Method::new({owner:?}, {name:?}, {descriptor:?}, {is_static}, {});",
                    return_type_const(descriptor)
                );
            }
        }
    }

    let bodies: Vec<String> = member
        .bindings
        .iter()
        .map(|binding| match binding {
            Binding::Direct { .. } => {
                let index = statics.iter().position(|other| *other == binding).unwrap();
                match member.kind {
                    Kind::Field => format!("Ok(cx.get(&T{index}, {this})?.{}()?)", accessor(ret)),
                    Kind::Constructor => format!("cx.construct(&T{index}, &[{jni_args}])"),
                    Kind::Method => format!(
                        "Ok(cx.call(&T{index}, {this}, &[{jni_args}])?.{}()?)",
                        accessor(ret)
                    ),
                }
            }
            Binding::Shim(function) => format!("crate::shims::{function}({shim_args})"),
            Binding::Unavailable => format!("Err(crate::unavailable(cx, {label:?}))"),
        })
        .collect();
    emit_match(out, &arms(model, &bodies));
    out.push_str("}\n\n");

    if member.setter {
        if member
            .bindings
            .iter()
            .any(|b| matches!(b, Binding::Shim(_)))
        {
            return Err(format!("{label}: a shimmed field cannot have a setter"));
        }
        let mut setter_signature = String::from("cx: &mut Cx<'l>");
        if has_this {
            setter_signature.push_str(", this: &JObject<'_>");
        }
        let _ = write!(setter_signature, ", value: {}", param_type(ret));
        let _ = writeln!(
            out,
            "/// Sets field `{}: {}`.",
            member.java, member.descriptor
        );
        let _ = writeln!(
            out,
            "pub fn set_{}<'l>({setter_signature}) -> Result<()> {{",
            member.rust
        );
        for (index, binding) in statics.iter().enumerate() {
            let Binding::Direct {
                class: owner,
                name,
                descriptor,
                is_static,
            } = binding
            else {
                unreachable!()
            };
            let _ = writeln!(
                out,
                "static T{index}: Field = Field::new({owner:?}, {name:?}, {descriptor:?}, {is_static});"
            );
        }
        let value = match ret {
            Ty::Object => "JValue::Object(value)",
            _ => "JValue::from(value)",
        };
        let bodies: Vec<String> = member
            .bindings
            .iter()
            .map(|binding| match binding {
                Binding::Direct { .. } => {
                    let index = statics.iter().position(|other| *other == binding).unwrap();
                    format!("cx.set(&T{index}, {this}, {value})")
                }
                _ => format!("Err(crate::unavailable(cx, {label:?}))"),
            })
            .collect();
        emit_match(out, &arms(model, &bodies));
        out.push_str("}\n\n");
    }
    Ok(())
}

fn emit_class(out: &mut String, model: &Model, class: &ApiClass) -> Result<(), String> {
    let _ = writeln!(out, "/// `{}`.", class.name);
    let renamed: Vec<String> = arms(model, &class.names)
        .into_iter()
        .filter_map(|(groups, name)| {
            let name = name?;
            (name != class.name).then(|| {
                let versions = groups
                    .iter()
                    .map(|group| group_versions(model, *group))
                    .collect::<Vec<_>>()
                    .join(", ");
                format!("/// - {versions}: `{name}`")
            })
        })
        .collect();
    if !renamed.is_empty() {
        out.push_str("///\n");
        for line in renamed {
            let _ = writeln!(out, "{line}");
        }
    }
    let _ = writeln!(out, "pub struct {};\n", class.rust);
    let _ = writeln!(out, "impl {} {{", class.rust);

    out.push_str("/// The class's JNI name on the running version.\n");
    out.push_str("pub fn class_name(cx: &mut Cx<'_>) -> Result<&'static str> {\n");
    let bodies: Vec<String> = class
        .names
        .iter()
        .map(|name| match name {
            Some(name) => format!("Ok({name:?})"),
            None => format!("Err(crate::unavailable(cx, {:?}))", class.rust),
        })
        .collect();
    emit_match(out, &arms(model, &bodies));
    out.push_str("}\n\n");
    out.push_str(
        "/// The class, resolved through the game class loader.\n\
         pub fn class<'l>(cx: &mut Cx<'l>) -> Result<JClass<'l>> {\n\
         let name = Self::class_name(cx)?;\n\
         cx.class(name)\n\
         }\n\n\
         /// Whether `object` is an instance of the class.\n\
         pub fn is_instance(cx: &mut Cx<'_>, object: &JObject<'_>) -> Result<bool> {\n\
         let name = Self::class_name(cx)?;\n\
         cx.is_instance_of(object, name)\n\
         }\n\n",
    );

    for member in &class.members {
        emit_member(out, model, class, member)?;
    }
    out.push_str("}\n\n");
    Ok(())
}

/// The bindings module.
pub fn bindings(model: &Model) -> Result<String, String> {
    let mut out = String::from(HEADER);
    out.push_str(
        "\n#![allow(unused_variables, clippy::all, clippy::pedantic)]\n\n\
         use jni::objects::{JClass, JObject, JValue};\n\
         use jni::signature::{Primitive, ReturnType};\n\
         use mc_runtime::{Cx, Field, Method, MinecraftVersion, Result};\n\n",
    );
    out.push_str("/// Every supported version: id, parsed form, binding group.\n");
    out.push_str("pub(crate) static VERSIONS: &[(&str, MinecraftVersion, usize)] = &[\n");
    for ((id, parsed), group) in model.versions.iter().zip(&model.groups) {
        let _ = writeln!(
            out,
            "({id:?}, MinecraftVersion::new({}, {}, {}), {group}),",
            parsed.major, parsed.minor, parsed.patch
        );
    }
    out.push_str("];\n\n");
    for class in &model.classes {
        emit_class(&mut out, model, class)?;
    }
    Ok(out)
}

/// The supported-version list for `mc-versions`.
pub fn supported(model: &Model) -> String {
    let mut out = String::from(HEADER);
    out.push_str(
        "\n/// Version ids — exactly as `version.json` / `WorldVersion.id()` report them —\n\
         /// on which every member the client binds resolves: one per dump in\n\
         /// `mc-data/dumps/`. Anything else, snapshots included, is refused unless\n\
         /// the user forces it.\n",
    );
    out.push_str("pub const SUPPORTED_VERSIONS: &[&str] = &[");
    let ids: Vec<String> = model
        .versions
        .iter()
        .map(|(id, _)| format!("{id:?}"))
        .collect();
    out.push_str(&ids.join(", "));
    out.push_str("];\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn descriptors_split_into_jni_value_types() {
        let (params, ret) = method_types("(ILjava/lang/String;[[D[Lx/Y;Z)V");
        assert!(
            params
                == [
                    Ty::Prim('I'),
                    Ty::Object,
                    Ty::Object,
                    Ty::Object,
                    Ty::Prim('Z')
                ]
        );
        assert!(ret == Ty::Prim('V'));
        let (params, ret) = method_types("()Lnet/minecraft/client/Camera;");
        assert!(params.is_empty() && ret == Ty::Object);
    }
}
